#pragma once#include <exception>class KSizeControllerS{private:  size_t m_CurPos;  size_t m_leftData;  const size_t m_Size;  BYTE *m_pData;  BYTE *m_pOnNextData;public:  KSizeControllerS( BYTE *data, size_t s )    : m_CurPos( 0 )    , m_pData( data )    , m_Size( s )  {    m_leftData = s;    if( !s )      m_pOnNextData = NULL;    else      m_pOnNextData = &m_pData[m_CurPos];  }  size_t Position()  {    return m_CurPos;  }  size_t LeftData()  {    return m_leftData;  }  template<typename T>  KSizeControllerS& operator >> ( T &v )  {    v = *(T*)GetValue( sizeof(T) );    return *this;  }  template<typename T>  T GetValue()  {    T r = *(T*)GetValue( sizeof(T) );    return r;  }  double GetDouble()  {    return GetValue<double>();  }  operator double()  {    return GetDouble();  }  double ReadDouble()  {    return GetDouble();  }  BYTE GetByte()  {    return GetValue<BYTE>();  }  operator BYTE()  {    return GetByte();  }  BYTE ReadByte()  {    return GetByte();  }  int GetInt()  {    return GetValue<int>();  }  operator int()  {    return GetInt();  }  DWORD GetDWORD()  {    return GetValue<DWORD>();  }  operator DWORD()  {    return GetDWORD();  }  WORD GetWORD()  {    return GetValue<WORD>();  }  operator WORD()  {    return GetWORD();  }  SHORT ReadInt16()  {    return GetValue<SHORT>();  }  BYTE* GetValue( size_t shift )  {    int iShift = (int)shift;    BYTE *r = (BYTE*)&m_pData[m_CurPos];    if( iShift >= 0 )      m_CurPos += shift;    else    {      shift = -iShift;      if( m_CurPos < shift )      {        m_pOnNextData = NULL;        throw std::exception("выход за пределы массива");      }      m_CurPos -= shift;    }    m_leftData = m_Size - m_CurPos;    if( m_CurPos == m_Size )      m_pOnNextData = NULL;    else if( m_CurPos > m_Size )    {      m_pOnNextData = NULL;      throw std::exception("выход за пределы массива");    }    else      m_pOnNextData = &m_pData[m_CurPos];    return r;  }  bool CanShiftOn( size_t shift )  {    size_t p = m_CurPos + shift;    if( p<=m_Size )      return true;    return false;  }  operator bool()  {    return (m_Size-m_CurPos) > 0;  }};template<typename T>KSizeControllerS& operator >> ( KSizeControllerS &is, T &val ){  val = is.GetValue<T>();  return is;}template<typename T, size_t C>KSizeControllerS& operator >> ( KSizeControllerS &is, T (&val)[C] ){  for( size_t i=0; i<C; i++ )    val[i] = is.GetValue<T>();  return is;}